import Nav from 'react-bootstrap/Nav';
import Tab from 'react-bootstrap/Tab';
import { Row, Col, Image, ListGroup, Button, Container } from 'react-bootstrap'
import Form from 'react-bootstrap/Form';
import { useEffect,useState } from 'react';
import axios from 'axios'


export default function FormulaScreen(props) {
  const [dataList, setDataList] = useState([]);

  useEffect(()=>{
     axios.get('/api/v1/electbill/').then(res => {
      console.log(res)
      dataList= res
      console.log(dataList[0])
     })

  },[])
    return(
        <div style={{direction:'rtl', marginTop:'50px'}}>
           {dataList?.map((item, index) =>
                                        <option value={item._id}>{item.subscriber.name}</option>
                                    )}

        <Tab.Container id="left-tabs-example" defaultActiveKey="first">
            <Row>


            </Row>
        <Row>
          <Col sm={3}>
            <Nav variant="pills" className="flex-column">
              <Nav.Item>
                <Nav.Link eventKey="first">Tab 1</Nav.Link>
              </Nav.Item>
              <Nav.Item>
                <Nav.Link eventKey="second">Tab 2</Nav.Link>
              </Nav.Item>
            </Nav>
          </Col>
          <Col sm={9}>
            <Tab.Content>
              <Tab.Pane eventKey="first">First tab content</Tab.Pane>
              <Tab.Pane eventKey="second">Second tab content</Tab.Pane>
            </Tab.Content>
          </Col>
        </Row>
      </Tab.Container>
</div>
    )
}
